// e2e tests for scripts/install.sh (repo root). They run the REAL script —
// clone, bun install, shim — but entirely inside a mkdtemp sandbox:
// HOME/XDG_DATA_HOME/OPENMEMORY_BIN_DIR point under the sandbox root and
// OPENMEMORY_REPO points at this repo via file://, so nothing touches the
// real ~/.local, ~/.claude, ~/.codex, or the network beyond bun's registry.
// The clone gets committed HEAD; the script under test is the working-tree
// copy invoked directly, so keep the two in sync by committing.
import { describe, expect, test } from "bun:test"
import { existsSync, mkdirSync, mkdtempSync, readFileSync, statSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join, resolve } from "node:path"

const repoRoot = resolve(import.meta.dir, "../..")
const script = join(repoRoot, "scripts", "install.sh")

function sandboxRoot(): string {
  return mkdtempSync(join(tmpdir(), "om-install-"))
}

function runInstall(root: string, env: Record<string, string> = {}) {
  return Bun.spawnSync(["bash", script], {
    env: {
      ...process.env,
      HOME: join(root, "home"),
      XDG_DATA_HOME: join(root, "data"),
      OPENMEMORY_INSTALL_DIR: join(root, "data", "openmemory", "src"),
      OPENMEMORY_BIN_DIR: join(root, "bin"),
      OPENMEMORY_REPO: `file://${repoRoot}`,
      ...env,
    },
    stdout: "pipe",
    stderr: "pipe",
  })
}

describe("install.sh", () => {
  test("shellcheck is clean (skipped when shellcheck is absent)", () => {
    if (!Bun.which("shellcheck")) return
    const res = Bun.spawnSync(["shellcheck", script], {
      stdout: "pipe",
      stderr: "pipe",
    })
    expect(res.stdout.toString()).toBe("")
    expect(res.exitCode).toBe(0)
  })

  test(
    "fresh install writes a working shim and hints about PATH",
    () => {
      const root = sandboxRoot()
      const res = runInstall(root)
      expect(res.stderr.toString()).toBe("")
      expect(res.exitCode).toBe(0)

      const shim = join(root, "bin", "openmemory")
      expect(existsSync(shim)).toBe(true)
      expect(statSync(shim).mode & 0o111).not.toBe(0)

      // sandbox bin dir is never on PATH, so the hint must appear
      expect(res.stdout.toString()).toContain("PATH")

      // shim works from a foreign cwd (the TUI preload depends on the
      // shim's cd; detect proves the wiring without needing a TTY)
      const detect = Bun.spawnSync([shim, "detect"], {
        cwd: tmpdir(),
        env: {
          ...process.env,
          HOME: join(root, "home"),
          XDG_DATA_HOME: join(root, "data"),
        },
        stdout: "pipe",
        stderr: "pipe",
      })
      expect(detect.exitCode).toBe(0)
      expect(detect.stdout.toString()).toContain("claude-code")
    },
    180_000,
  )

  test(
    "re-run updates in place instead of re-cloning",
    () => {
      const root = sandboxRoot()
      expect(runInstall(root).exitCode).toBe(0)

      // a marker inside the checkout survives only if the second run
      // pulls instead of deleting/re-cloning
      const marker = join(root, "data", "openmemory", "src", ".test-marker")
      writeFileSync(marker, "still here")

      const second = runInstall(root)
      expect(second.exitCode).toBe(0)
      expect(existsSync(marker)).toBe(true)
      expect(existsSync(join(root, "bin", "openmemory"))).toBe(true)
    },
    180_000,
  )

  test(
    "warns before replacing an unrelated openmemory binary",
    () => {
      const root = sandboxRoot()
      const bin = join(root, "bin")
      mkdirSync(bin, { recursive: true })
      const shim = join(bin, "openmemory")
      writeFileSync(shim, "#!/bin/sh\necho other tool\n")

      const res = runInstall(root)
      expect(res.exitCode).toBe(0)
      expect(res.stdout.toString()).toMatch(/replac/i)
      expect(readFileSync(shim, "utf8")).toContain("Managed by openmemory")
    },
    180_000,
  )

  test(
    "fails when the shim path is a directory",
    () => {
      const root = sandboxRoot()
      mkdirSync(join(root, "bin", "openmemory"), { recursive: true })

      const res = runInstall(root)
      expect(res.exitCode).not.toBe(0)
      expect(res.stderr.toString()).toContain("is a directory")
    },
    180_000,
  )

  test(
    "refuses to clobber a pre-existing non-git directory",
    () => {
      const root = sandboxRoot()
      const src = join(root, "data", "openmemory", "src")
      mkdirSync(src, { recursive: true })
      writeFileSync(join(src, "keep.txt"), "user data")

      const res = runInstall(root)
      expect(res.exitCode).not.toBe(0)
      expect(res.stderr.toString()).toContain("not a git checkout")
      expect(existsSync(join(src, "keep.txt"))).toBe(true)
    },
    180_000,
  )
})

